/**
 * pyargparse.mjs
 *
 * A byte-for-byte emulation of CPython 3.12 `argparse` for exactly this parser:
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--domain', type=str, required=True)
 *     args = parser.parse_args()
 *
 * The logic below is a direct transliteration of the relevant parts of
 * /usr/lib/python3.12/argparse.py (ArgumentParser._parse_known_args,
 * _parse_optional, _get_option_tuples, _match_argument, HelpFormatter).
 * Behaviour was verified against the frozen reference binary; see
 * argparse-findings.md.
 *
 * Node.js ESM, zero external dependencies.
 */

import { writeSync } from 'node:fs';

// ---------------------------------------------------------------------------
// Low-level output helpers
// ---------------------------------------------------------------------------

/**
 * Synchronous, unbuffered write to a file descriptor.
 *
 * Python writes to sys.stdout/sys.stderr and flushes on exit. `process.exit()`
 * in Node can truncate pending asynchronous writes on a pipe, so we bypass the
 * stream layer entirely. Non-blocking pipes can raise EAGAIN; retry those.
 */
function writeFd(fd, text) {
  const buf = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buf.length) {
    try {
      offset += writeSync(fd, buf, offset, buf.length - offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue;
      if (err.code === 'EPIPE') return;
      throw err;
    }
  }
}

// ---------------------------------------------------------------------------
// Python helpers
// ---------------------------------------------------------------------------

/** POSIX os.path.basename: everything after the last '/'. */
export function basename(p) {
  const i = String(p).lastIndexOf('/');
  return i === -1 ? String(p) : String(p).slice(i + 1);
}

/** Default prog, matching Python's `os.path.basename(sys.argv[0])`. */
export function defaultProgName() {
  return basename(process.argv[1] ?? '');
}

/**
 * Approximation of Python 3 `repr()` for a str. Only used by the
 * "ignored explicit argument %r" error path.
 */
function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else out += ch;
  }
  return out + quote;
}

/**
 * shutil.get_terminal_size().columns — COLUMNS env wins when it is a positive
 * integer, then the real terminal size, then the (80, 24) fallback.
 */
function terminalColumns() {
  const env = process.env.COLUMNS;
  let columns = 0;
  if (env !== undefined && /^[ \t\n\r]*[+-]?\d+[ \t\n\r]*$/.test(env)) {
    columns = parseInt(env, 10);
  }
  if (columns <= 0) {
    columns = (process.stdout && process.stdout.columns) || 80;
  }
  return columns;
}

/**
 * textwrap.wrap() with argparse's defaults: collapse whitespace runs, greedy
 * fill, break words that are longer than the available width.
 */
function textWrap(text, width) {
  const collapsed = text.replace(/\s+/g, ' ').trim();
  if (!collapsed) return [];
  const lines = [];
  let line = '';
  for (let word of collapsed.split(' ')) {
    while (word.length > width) {
      // break_long_words=True: emit as much of the word as fits
      if (line) {
        lines.push(line);
        line = '';
      }
      lines.push(word.slice(0, width));
      word = word.slice(width);
    }
    if (!line) line = word;
    else if (line.length + 1 + word.length <= width) line += ' ' + word;
    else {
      lines.push(line);
      line = word;
    }
  }
  if (line) lines.push(line);
  return lines;
}

