// ---------------------------------------------------------------------------

const PREFIX_CHARS = '-';

/** argparse's ArgumentParser._negative_number_matcher (3.12). */
const NEGATIVE_NUMBER_MATCHER = /^-\d+$|^-\d*\.\d+$/;

const HELP_ACTION = {
  optionStrings: ['-h', '--help'],
  dest: 'help',
  nargs: 0,
  required: false,
  help: 'show this help message and exit',
  isHelp: true,
};

const DOMAIN_ACTION = {
  optionStrings: ['--domain'],
  dest: 'domain',
  nargs: null, // nargs=None => exactly one value
  required: true,
  help: null,
  isHelp: false,
};

const ACTIONS = [HELP_ACTION, DOMAIN_ACTION];

/**
 * _option_string_actions. Insertion order matters: it drives the order of the
 * candidate list in "ambiguous option: ... could match --help, --domain".
 */
const OPTION_STRING_ACTIONS = new Map([
  ['-h', HELP_ACTION],
  ['--help', HELP_ACTION],
  ['--domain', DOMAIN_ACTION],
]);

/**
 * _has_negative_number_optionals: true when any option string itself looks
 * like a negative number. None of '-h', '--help', '--domain' does, so a token
 * such as "-5" is accepted as a value rather than read as an option.
 */
