}

/** ArgumentError: "argument <name>: <message>" */
class ArgumentError extends Error {
  constructor(action, message) {
    super(`argument ${actionName(action)}: ${message}`);
    this.name = 'ArgumentError';
  }
}

/** Thrown internally to unwind to the top-level exit handler. */
class ExitSignal extends Error {
  constructor(code) {
    super(`exit ${code}`);
    this.code = code;
  }
}

// ---------------------------------------------------------------------------
// Help / usage formatting (HelpFormatter)
// ---------------------------------------------------------------------------

const INDENT_INCREMENT = 2;
const DEFAULT_MAX_HELP_POSITION = 24;

/** HelpFormatter._format_actions_usage, specialised to our optionals. */
function formatActionsUsage(actions) {
  const parts = [];
  for (const action of actions) {
    let part;
    if (action.nargs === 0) {
      part = action.optionStrings[0];
    } else {
      part = `${action.optionStrings[0]} ${metavarFor(action)}`;
    }
    if (!action.required) part = `[${part}]`;
    parts.push(part);
