/**
 * HelpFormatter._format_usage, including the long-prog wrapping branch.
 * Returns the usage block *with* its trailing "\n\n".
 */
export function formatUsageBlock(prog, width = terminalColumns() - 2) {
  const prefix = 'usage: ';
  const optionals = ACTIONS.filter((a) => a.optionStrings.length);
  const positionals = [];
  const actionUsage = formatActionsUsage([...optionals, ...positionals]);
