    const posUsage = formatActionsUsage(positionals);
    const optParts = optUsage.match(partRegexp) ?? [];
    const posParts = posUsage.match(partRegexp) ?? [];

    const getLines = (parts, indent, linePrefix) => {
      const lines = [];
      let line = [];
      const indentLength = indent.length;
      let lineLen = (linePrefix !== undefined ? linePrefix.length : indentLength) - 1;
      for (const part of parts) {
        if (lineLen + 1 + part.length > textWidth && line.length) {
          lines.push(indent + line.join(' '));
          line = [];
          lineLen = indentLength - 1;
        }
        line.push(part);
        lineLen += part.length + 1;
      }
      if (line.length) lines.push(indent + line.join(' '));
      if (linePrefix !== undefined && lines.length) lines[0] = lines[0].slice(indentLength);
      return lines;
    };

    let lines;
    if (prefix.length + prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(prefix.length + prog.length + 1);
      if (optParts.length) {
        lines = getLines([prog, ...optParts], indent, prefix);
        lines.push(...getLines(posParts, indent));
      } else if (posParts.length) {
        lines = getLines([prog, ...posParts], indent, prefix);
      } else {
        lines = [prog];
      }
    } else {
      const indent = ' '.repeat(prefix.length);
      lines = getLines([...optParts, ...posParts], indent);
      if (lines.length > 1) {
        lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
      }
      lines = [prog, ...lines];
