export function formatUsage(prog = defaultProgName(), width = terminalColumns() - 2) {
  return formatUsageBlock(prog, width).replace(/\n+$/, '\n');
}

/** HelpFormatter._format_action_invocation */
function formatActionInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  const args = metavarFor(action);
  return action.optionStrings.map((s) => `${s} ${args}`).join(', ');
