    const m = new RegExp('^' + nargsPattern(action)).exec(patternSlice);
    if (m === null) {
      // nargs=None => "expected one argument"; nargs=0 always matches.
      throw new ArgumentError(action, 'expected one argument');
    }
    return m[1].length;
  }

  // -- Namespace mutation ----------------------------------------------------
  const seenActions = new Set();

  /** ArgumentParser._get_values, narrowed to our two actions. */
  function getValues(action, args) {
    if (args.length === 1 && action.nargs === null) return args[0]; // type=str
    return args.slice();
  }

  function takeAction(action, args) {
    seenActions.add(action);
    const value = getValues(action, args);
    if (action.isHelp) {
      writeFd(1, formatHelp(prog, width));
      throw new ExitSignal(0);
    }
    namespace[action.dest] = value;
  }

  // -- Build the option index and the arg-string pattern ---------------------
  const optionStringIndices = new Map();
  const patternParts = [];
  for (let i = 0; i < argStrings.length; i++) {
    if (argStrings[i] === '--') {
      // everything after the FIRST '--' is a non-option
      patternParts.push('-');
      for (let j = i + 1; j < argStrings.length; j++) patternParts.push('A');
      break;
    }
    const tuple = parseOptional(argStrings[i]);
    if (tuple === null) {
      patternParts.push('A');
    } else {
      optionStringIndices.set(i, tuple);
      patternParts.push('O');
    }
  }
  const argStringsPattern = patternParts.join('');

  const extras = [];

  // -- ArgumentParser._parse_known_args.consume_optional --------------------
  function consumeOptional(startIndex) {
    let { action, optionString, sep, explicitArg } = optionStringIndices.get(startIndex);
    const actionTuples = [];
    let stop;

    for (;;) {
      if (action === null) {
        extras.push(argStrings[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = matchArgument(action, 'A');

        if (argCount === 0 && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          // single-dash option with no argument: try to peel more short options
          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
          actionTuples.push([action, []]);
          const char = optionString[0];
          const nextOptionString = char + explicitArg[0];
          if (OPTION_STRING_ACTIONS.has(nextOptionString)) {
            optionString = nextOptionString;
            action = OPTION_STRING_ACTIONS.get(nextOptionString);
            explicitArg = explicitArg.slice(1);
            if (explicitArg === '') {
              sep = null;
              explicitArg = null;
            } else if (explicitArg[0] === '=') {
              sep = '=';
              explicitArg = explicitArg.slice(1);
            } else {
              sep = '';
            }
          } else {
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push([action, [explicitArg]]);
          break;
        } else {
          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
        }
      } else {
        const start = startIndex + 1;
        const argCount = matchArgument(action, argStringsPattern.slice(start));
        stop = start + argCount;
        actionTuples.push([action, argStrings.slice(start, stop)]);
        break;
      }
    }

    for (const [a, args] of actionTuples) takeAction(a, args);
    return stop;
  }

  // -- Main consume loop -----------------------------------------------------
  // This parser has no positional actions, so consume_positionals() is a no-op
  // that always returns start_index unchanged; the branches that depend on it
  // making progress are therefore dead and are elided.
  try {
    const indices = [...optionStringIndices.keys()];
    const maxOptionStringIndex = indices.length ? Math.max(...indices) : -1;
    let startIndex = 0;
    while (startIndex <= maxOptionStringIndex) {
      let nextOptionStringIndex = Infinity;
      for (const i of indices) {
        if (i >= startIndex && i < nextOptionStringIndex) nextOptionStringIndex = i;
      }
      if (!optionStringIndices.has(startIndex)) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }
      startIndex = consumeOptional(startIndex);
    }
    extras.push(...argStrings.slice(startIndex));
  } catch (err) {
    if (err instanceof ArgumentError) error(err.message);
    throw err;
  }

  // -- Required check (inside parse_known_args, BEFORE unrecognized args) ----
  const requiredMissing = ACTIONS.filter((a) => a.required && !seenActions.has(a)).map(actionName);
  if (requiredMissing.length) {
    error(`the following arguments are required: ${requiredMissing.join(', ')}`);
  }

  // -- parse_args: leftover arg strings --------------------------------------
  if (extras.length) {
    error(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { domain: namespace.domain };
}

/**
 * pyargparse-selftest.mjs
 *
 * Differential self-test: runs every case through the JS port in a child
 * process and compares exit code / stdout / stderr byte-for-byte against the
 * captured CPython 3.12 argparse reference output in local_results.json
 * (which was itself confirmed against the frozen oracle binary).
 *
 * Usage:
 *   node pyargparse-selftest.mjs                     # run the suite
 *   node pyargparse-selftest.mjs --child PROG -- ...  # act as the program
 */

import { spawnSync } from 'node:child_process';
import { readFileSync, writeSync } from 'node:fs';
import { parseArgs } from './pyargparse.mjs';

const SELF = new URL(import.meta.url).pathname;
const RESULTS = '/tmp/wf/local_results.json';

// --------------------------------------------------------------------------
// Child mode: behave like the ported program.
// --------------------------------------------------------------------------
if (process.argv[2] === '--child') {
  const prog = process.argv[3];
  const args = process.argv.slice(5); // skip the '--' at index 4
  const { domain } = parseArgs(args, prog);
  // Mirror the reference harness: OK <python repr of the string>
  const repr = "'" + domain.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
  writeSync(1, `OK ${repr}\n`);
  process.exit(0);
}

// --------------------------------------------------------------------------
// Suite mode
// --------------------------------------------------------------------------
const expected = JSON.parse(readFileSync(RESULTS, 'utf8'));

let pass = 0;
const failures = [];

for (const exp of expected) {
  const r = spawnSync(
    process.execPath,
    [SELF, '--child', 'test1_executable', '--', ...exp.argv],
    { encoding: 'utf8', env: { ...process.env, COLUMNS: '' } },
  );
  const got = { code: r.status, out: r.stdout, err: r.stderr };
  if (got.code === exp.code && got.out === exp.out && got.err === exp.err) {
    pass++;
  } else {
    failures.push({ argv: exp.argv, expected: exp, got });
  }
}

for (const f of failures) {
  console.log('FAIL', JSON.stringify(f.argv));
  console.log('  exp code', f.expected.code, 'out', JSON.stringify(f.expected.out), 'err', JSON.stringify(f.expected.err));
  console.log('  got code', f.got.code, 'out', JSON.stringify(f.got.out), 'err', JSON.stringify(f.got.err));
}
console.log(`\n${pass}/${expected.length} passed, ${failures.length} failed`);
process.exit(failures.length ? 1 : 0);

